<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Arena updates</p><h1 class="mt-2 text-3xl font-black">Announcements</h1><p class="mt-2 text-sm text-slate-400">Write and publish notices visible to players on the home page.</p></div>
  <form method="post" action="<?= h(app_url('index.php?action=admin-announcement-save')) ?>" class="glass-card mt-5 grid gap-4 rounded-2xl p-5 sm:grid-cols-2"><?= csrf_field() ?><label class="text-xs font-bold text-slate-400 sm:col-span-2">Announcement title<input class="form-control mt-2" name="title" maxlength="140" required></label><label class="text-xs font-bold text-slate-400 sm:col-span-2">Message<textarea class="form-control mt-2 min-h-24" name="body" maxlength="5000" required></textarea></label><label class="flex items-center gap-2 text-xs font-bold text-slate-300"><input type="checkbox" name="publish" value="1">Publish now</label><div><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Save announcement</button></div></form>
  <section class="mt-5 space-y-3"><?php if(!$announcements): ?><div class="glass-card rounded-2xl p-8 text-center text-sm text-slate-500">No announcements yet.</div><?php endif; ?><?php foreach($announcements as $item): ?><article class="glass-card rounded-2xl p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div><div class="flex items-center gap-2"><h2 class="font-black"><?= h($item['title']) ?></h2><span class="badge <?= $item['status']==='published'?'badge-open':'badge-soon' ?>"><?= h($item['status']) ?></span></div><p class="mt-3 whitespace-pre-line text-sm leading-6 text-slate-400"><?= h($item['body']) ?></p><p class="mt-3 text-[10px] text-slate-600"><?= h(date('d M Y · g:i A',strtotime((string)$item['created_at'].' UTC'))) ?> · <?= h($item['email']) ?></p></div><form method="post" action="<?= h(app_url('index.php?action=admin-announcement-toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="announcement_id" value="<?= h($item['id']) ?>"><button class="rounded-xl border border-white/10 px-3 py-2 text-[10px] font-bold"><?= $item['status']==='published'?'Archive':'Publish' ?></button></form></div></article><?php endforeach; ?></section>
</main>
